const a = 2;
const b = 5;
const c = 3;

// The quadratic formula is: x = (-b ± sqrt(b^2 - 4ac)) / 2a
// The discriminant is: D = b^2 - 4ac
const discriminant = b * b - 4 * a * c;

if (discriminant < 0) {
  console.log("The roots are complex:", (-b / 2 * Math.sqrt(-1) + Math.sqrt(-discriminant)) / a, (-b / 2 * Math.sqrt(-1) - Math.sqrt(-discriminant)) / a);
} else if (discriminant === 0) {
  const root = -b / (2 * a);
  console.log("The roots are equal:", root);
} else {
  const root1 = (-b + Math.sqrt(discriminant)) / (2 * a);
  const root2 = (-b - Math.sqrt(discriminant)) / (2 * a);
  console.log("The roots are:", root1, "and", root2);
}
